CREATE TYPE "StatusContaReceber" AS ENUM ('PENDENTE', 'PARCIAL', 'RECEBIDO', 'VENCIDO', 'CANCELADO');
CREATE TYPE "StatusSessaoCaixa" AS ENUM ('ABERTO', 'FECHADO');
CREATE TYPE "TipoMovimentoCaixa" AS ENUM ('SANGRIA', 'SUPRIMENTO');
CREATE TYPE "TipoMovimentoEstoque" AS ENUM ('ENTRADA', 'SAIDA', 'AJUSTE_ESTORNO');
CREATE TABLE "ContaReceber" ("id" SERIAL PRIMARY KEY,"descricao" VARCHAR(255) NOT NULL,"valorOriginal" DOUBLE PRECISION NOT NULL,"valorRecebido" DOUBLE PRECISION NOT NULL DEFAULT 0,"juros" DOUBLE PRECISION NOT NULL DEFAULT 0,"multa" DOUBLE PRECISION NOT NULL DEFAULT 0,"desconto" DOUBLE PRECISION NOT NULL DEFAULT 0,"vencimento" TIMESTAMP(3) NOT NULL,"recebidaEm" TIMESTAMP(3),"status" "StatusContaReceber" NOT NULL DEFAULT 'PENDENTE',"parcela" INTEGER NOT NULL DEFAULT 1,"totalParcelas" INTEGER NOT NULL DEFAULT 1,"empresaId" INTEGER NOT NULL,"clienteId" INTEGER,"vendaId" INTEGER,"criadoEm" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"atualizadoEm" TIMESTAMP(3) NOT NULL);
CREATE TABLE "RecebimentoConta" ("id" SERIAL PRIMARY KEY,"contaId" INTEGER NOT NULL,"valor" DOUBLE PRECISION NOT NULL,"juros" DOUBLE PRECISION NOT NULL DEFAULT 0,"multa" DOUBLE PRECISION NOT NULL DEFAULT 0,"desconto" DOUBLE PRECISION NOT NULL DEFAULT 0,"meioPagamento" "MeioPagamento" NOT NULL,"dataRecebimento" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"observacao" VARCHAR(500),"criadoEm" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SessaoCaixa" ("id" SERIAL PRIMARY KEY,"empresaId" INTEGER NOT NULL,"usuarioId" INTEGER,"abertoEm" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"fechadoEm" TIMESTAMP(3),"valorAbertura" DOUBLE PRECISION NOT NULL,"valorEsperado" DOUBLE PRECISION,"valorContado" DOUBLE PRECISION,"diferenca" DOUBLE PRECISION,"status" "StatusSessaoCaixa" NOT NULL DEFAULT 'ABERTO',"observacaoAbertura" VARCHAR(500),"observacaoFechamento" VARCHAR(500));
CREATE TABLE "MovimentoCaixa" ("id" SERIAL PRIMARY KEY,"sessaoId" INTEGER NOT NULL,"tipo" "TipoMovimentoCaixa" NOT NULL,"valor" DOUBLE PRECISION NOT NULL,"descricao" VARCHAR(255),"criadoEm" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "MovimentoEstoque" ("id" SERIAL PRIMARY KEY,"produtoId" INTEGER NOT NULL,"empresaId" INTEGER NOT NULL,"tipo" "TipoMovimentoEstoque" NOT NULL,"quantidade" DOUBLE PRECISION NOT NULL,"estoqueAnterior" DOUBLE PRECISION NOT NULL,"estoquePosterior" DOUBLE PRECISION NOT NULL,"custoUnitario" DOUBLE PRECISION,"motivo" VARCHAR(255) NOT NULL,"referencia" VARCHAR(100),"criadoEm" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE "ContaReceber" ADD CONSTRAINT "ContaReceber_empresaId_fkey" FOREIGN KEY ("empresaId") REFERENCES "Empresa"("id") ON DELETE CASCADE; ALTER TABLE "ContaReceber" ADD CONSTRAINT "ContaReceber_clienteId_fkey" FOREIGN KEY ("clienteId") REFERENCES "Cliente"("id") ON DELETE SET NULL; ALTER TABLE "ContaReceber" ADD CONSTRAINT "ContaReceber_vendaId_fkey" FOREIGN KEY ("vendaId") REFERENCES "Venda"("id") ON DELETE SET NULL; ALTER TABLE "RecebimentoConta" ADD CONSTRAINT "RecebimentoConta_contaId_fkey" FOREIGN KEY ("contaId") REFERENCES "ContaReceber"("id") ON DELETE CASCADE; ALTER TABLE "SessaoCaixa" ADD CONSTRAINT "SessaoCaixa_empresaId_fkey" FOREIGN KEY ("empresaId") REFERENCES "Empresa"("id") ON DELETE CASCADE; ALTER TABLE "MovimentoCaixa" ADD CONSTRAINT "MovimentoCaixa_sessaoId_fkey" FOREIGN KEY ("sessaoId") REFERENCES "SessaoCaixa"("id") ON DELETE CASCADE; ALTER TABLE "MovimentoEstoque" ADD CONSTRAINT "MovimentoEstoque_produtoId_fkey" FOREIGN KEY ("produtoId") REFERENCES "Produto"("id") ON DELETE CASCADE; ALTER TABLE "MovimentoEstoque" ADD CONSTRAINT "MovimentoEstoque_empresaId_fkey" FOREIGN KEY ("empresaId") REFERENCES "Empresa"("id") ON DELETE CASCADE;
